int CompareCapcodes(char *szCapcode1, char *szCapcode2)
{
	for (int i=0; i<9; i++) 
	{
		if(szCapcode1[i] > szCapcode2[i]) return(1) ;
		if(szCapcode1[i] < szCapcode2[i]) return(-1) ;
	}
	return(0) ;
}

